svg.script:
(() => {
  const root = document.documentElement;
  const hit = document.getElementById("hit-area");
  const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)");
  const duration = 240;
  const liftDuration = 105;
  let state = root.dataset.state === "right" ? "right" : "left";
  let transitionTimer = 0;
  let liftTimer = 0;

  function syncAria() {
    const isRight = state === "right";
    hit.setAttribute("aria-pressed", String(isRight));
    hit.setAttribute("aria-label", isRight ? "切换到旋钮在左侧的状态" : "切换到旋钮在右侧的状态");
  }

  function setState(next, animate = true) {
    const nextState = next === "right" || next === 1 || next === true ? "right" : "left";
    if (nextState === state && !animate) {
      syncAria();
      return;
    }
    state = nextState;
    root.dataset.state = state;
    const shouldAnimate = animate && !reduce?.matches;
    root.dataset.motion = shouldAnimate ? "animated" : "instant";
    root.classList.toggle("is-transitioning", shouldAnimate);
    syncAria();
    clearTimeout(transitionTimer);
    clearTimeout(liftTimer);
    if (shouldAnimate) {
      liftTimer = window.setTimeout(() => {
        root.classList.remove("is-transitioning");
      }, liftDuration);
      transitionTimer = window.setTimeout(() => {
        root.removeAttribute("data-motion");
      }, duration + 20);
    } else {
      root.classList.remove("is-transitioning");
      window.setTimeout(() => root.removeAttribute("data-motion"), 0);
    }
  }

  function toggle(animate = true) {
    setState(state === "right" ? "left" : "right", animate);
  }

  window.setKnobState = setState;
  window.toggleKnob = toggle;
  window.replayKnob = () => {
    const original = state;
    setState(original === "right" ? "left" : "right", false);
    window.setTimeout(() => setState(original, true), 24);
  };

  hit.addEventListener("click", () => toggle(true));
  hit.addEventListener("keydown", (event) => {
    if (["Enter", " "].includes(event.key)) {
      event.preventDefault();
      toggle(true);
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      setState("left", false);
    }
    if (event.key === "ArrowRight") {
      event.preventDefault();
      setState("right", false);
    }
  });

  syncAria();
})();
